"""Build two offline guides for the seminar simulator."""
from pathlib import Path
import html
OUT=Path(__file__).resolve().parents[1]/'seminar'
rows=[
('Target angle','45°','Half-angle of the target-facing visibility cone. Larger values admit more sideward candidates. Used only in fixed mode.'),
('Staging angle','60°','Half-angle toward the chosen staging anchor. Larger values admit more detours toward that anchor. Used only in fixed mode.'),
('Dynamic min angle','30°','Lower bound for the distance-dependent angle. Farther sources receive narrower cones.'),
('Dynamic max angle','60°','Upper bound for the distance-dependent angle. Nearer sources receive wider cones. The editor keeps min ≤ max.'),
('Visibility range factor','1','Limits target successor distance to this factor times distance to the target boundary. Smaller values shorten connections; the terminal fallback still exists.'),
('Path length factor','2','Maximum charged target-route length relative to straight distance to the target. Larger values permit longer collection routes. This control does not currently cap staging-route search.'),
('Own-path heat weight','0','Weights the occupied source’s own heat component. At 0, heat comes only from other sources. Increasing it can make more occupied sources exceed the staging threshold.'),
('Alignment exponent','1','Raises positive directional alignment to this power. Above 1 suppresses off-axis heat; below 1 spreads it more broadly.'),
('Heat radial gate','75°','Target-relative angular rejection gate for a heat contribution. Smaller angles reject more contributions before alignment is evaluated.'),
('Anchor min heat ratio','0.30','A staging destination must reach this fraction of the map’s maximum heat. Increasing it restricts anchor candidates.'),
('High-heat threshold','0.50','Sources at or above this fraction of maximum heat are skipped by staging-path construction. Increasing it makes more sources eligible for staging.'),
('Heat weight','0.70','Balances anchor heat against proximity. The editor sets distance weight to 1 minus this value. It affects anchor choice, not target-route reward.'),
('Spillage coefficient','0.05','Multiplies curvature and current load in the approximate spill model. Higher values tend to increase predicted losses, with threshold and rounding effects.'),
('Minimum spill','0.03','Loss below this per-sample threshold is ignored. Increasing it suppresses small predicted deposits. It is not a geometric distance or a material fraction.'),
]
style='''<style>body{font:17px/1.6 system-ui;color:#193447;max-width:1100px;margin:35px auto;padding:0 24px}h1,h2{line-height:1.2}h2{margin-top:34px}table{border-collapse:collapse;width:100%;font-size:15px}th,td{border:1px solid #ccd6dc;padding:9px;text-align:left;vertical-align:top}th{background:#e9f1f4}code,pre{background:#edf2f5}pre{padding:15px;white-space:pre-wrap}a{color:#007083}.note{border-left:4px solid #dc941f;padding:10px 18px;background:#fff7e7}@media print{tr{break-inside:avoid}}</style>'''
